//! Integration tests for the PDF 2.0 (ISO 32000-2) fixtures in `tests/fixtures/`.
//!
//! Fixtures are generated by the committed writer-based generator
//! (`examples/generate_pdf2_fixtures.rs`) — re-run it and diff the output
//! after any writer change.
//!
//! Fixture notes:
//! - `pdf2-signed-ltv.pdf` exists for **DSS parsing** (PDF 2.0 Phase D); its
//!   signature `/Contents` bytes are intentionally placeholders, not a valid
//!   CMS structure.
//! - `pdf2-encrypted-r6.pdf` (plan Phase F) is deferred until writer-side R6
//!   encryption exists; the R6 read path stays covered by crafted-bytes
//!   unit tests in `src/crypto`.

#[cfg(feature = "writer")]
mod pdf2_fixtures {
    use pdf_core::parser::objects::PdfDocument;

    fn fixture(name: &str) -> Vec<u8> {
        let path = format!("{}/tests/fixtures/{}", env!("CARGO_MANIFEST_DIR"), name);
        std::fs::read(&path).unwrap_or_else(|e| panic!("read {path}: {e}"))
    }

    #[test]
    fn pdf2_minimal_parses_with_v2_0() {
        let doc = PdfDocument::parse(fixture("pdf2-minimal.pdf")).expect("parse");
        assert_eq!(doc.version(), pdf_core::parser::version::PdfVersion::V2_0);
    }

    #[test]
    fn pdf2_associated_files_fixture_lists_af() {
        let bytes = fixture("pdf2-associated-files.pdf");
        assert!(bytes.starts_with(b"%PDF-2.0"));
        let doc = PdfDocument::parse(bytes).expect("parse");
        let catalog = pdf_core::document::catalog::Catalog::from_document(&doc).expect("catalog");
        let specs = catalog.associated_files(&doc).expect("af parse");
        assert_eq!(specs.len(), 1);
        assert_eq!(
            specs[0].relationship,
            pdf_core::document::associated_files::AfRelationship::Supplement
        );
        // /UF is required in 2.0 — the writer always emits it.
        assert_eq!(specs[0].name_uf.as_deref(), Some("dataset.csv"));
        assert!(specs[0].display_name().is_some());
    }

    #[cfg(feature = "signatures")]
    #[test]
    fn pdf2_signed_ltv_fixture_exposes_dss() {
        use pdf_core::signatures::{parse_dss, DssPayload};
        let bytes = fixture("pdf2-signed-ltv.pdf");
        let doc = PdfDocument::parse(bytes).expect("parse");
        assert_eq!(doc.version(), pdf_core::parser::version::PdfVersion::V2_0);

        let catalog = doc
            .resolve(&doc.trailer.get("Root").expect("Root in trailer").clone())
            .expect("resolve Root")
            .as_dict()
            .expect("Root is a dict")
            .clone();
        let dss = parse_dss(&doc, &catalog)
            .expect("dss parse")
            .expect("dss present");

        assert_eq!(dss.certs.len(), 1);
        assert_eq!(dss.ocsps.len(), 1);
        assert_eq!(dss.crls.len(), 1);
        assert_eq!(dss.vri.len(), 1);
        assert!(matches!(dss.certs[0].payload, DssPayload::Reference { .. }));

        // DER bytes come through the stream pipeline intact.
        assert_eq!(dss.certs[0].der(&doc).expect("cert der"), b"DER-CERT-POOL");
        assert_eq!(dss.crls[0].der(&doc).expect("crl der"), b"DER-CRL-POOL");
        assert_eq!(
            dss.vri[0]
                .ts_ref
                .as_ref()
                .expect("ts")
                .der(&doc)
                .expect("ts der"),
            b"DER-TS-TOKEN"
        );
    }
}
